import BlogList from '../components/BlogList';
import BlogForm from '../components/BlogForm';

const Home = () => {
  return (
    <div className="container mx-auto p-4">
      <h1 className="text-3xl font-bold mb-4">Blog App</h1>
      <BlogForm />
      <BlogList />
    </div>
  );
};

export default Home;
